alter table public.agents add constraint agents_model_tier_check CHECK ((model_tier = ANY (ARRAY['cheap'::text, 'standard'::text, 'strong'::text])));
alter table public.agents add constraint agents_role_check CHECK ((role = ANY (ARRAY['owner_contact'::text, 'ceo'::text, 'coo'::text, 'cfo'::text, 'hr'::text, 'builder'::text, 'gm'::text, 'ops'::text, 'finance'::text, 'auditor'::text, 'researcher'::text, 'specialist'::text, 'compliance'::text, 'shared'::text])));
alter table public.agents add constraint agents_status_check CHECK ((status = ANY (ARRAY['active'::text, 'paused'::text])));
alter table public.departments add constraint departments_kind_check CHECK ((kind = ANY (ARRAY['venture'::text, 'shared'::text, 'holding'::text])));
alter table public.departments add constraint departments_status_check CHECK ((status = ANY (ARRAY['active'::text, 'paused'::text, 'parked'::text])));
alter table public.escalations add constraint escalations_kind_check CHECK ((kind = ANY (ARRAY['conflict'::text, 'uncertain'::text, 'cross_department'::text, 'owner_decision'::text, 'failure'::text])));
alter table public.escalations add constraint escalations_status_check CHECK ((status = ANY (ARRAY['open'::text, 'resolved_by_auditor'::text, 'with_jarvis'::text, 'sent_to_owner'::text, 'closed'::text])));
alter table public.ideas add constraint ideas_status_check CHECK ((status = ANY (ARRAY['new'::text, 'testing'::text, 'scaled'::text, 'killed'::text, 'parked'::text])));
alter table public.ledger add constraint ledger_kind_check CHECK ((kind = ANY (ARRAY['revenue'::text, 'expense'::text, 'tax_setaside'::text, 'reinvestment'::text])));
alter table public.ledger add constraint ledger_status_check CHECK ((status = ANY (ARRAY['expected'::text, 'received'::text])));
alter table public.llm_calls add constraint llm_calls_status_check CHECK ((status = ANY (ARRAY['reserved'::text, 'done'::text, 'failed'::text, 'released'::text])));
alter table public.memory add constraint memory_confidence_check CHECK ((confidence = ANY (ARRAY['high'::text, 'medium'::text, 'low'::text, 'unverified'::text])));
alter table public.memory add constraint memory_fact_needs_source CHECK (((kind <> 'fact'::text) OR (source IS NOT NULL)));
alter table public.memory add constraint memory_kind_check CHECK ((kind = ANY (ARRAY['lesson'::text, 'decision'::text, 'outcome'::text, 'fact'::text])));
alter table public.missions add constraint missions_budget_cents_check CHECK (((budget_cents >= 0) AND (budget_cents <= 2000)));
alter table public.missions add constraint missions_objective_check CHECK (((length(objective) >= 10) AND (length(objective) <= 4000)));
alter table public.missions add constraint missions_priority_check CHECK (((priority >= 1) AND (priority <= 5)));
alter table public.missions add constraint missions_status_check CHECK ((status = ANY (ARRAY['captured'::text, 'evaluated'::text, 'planned'::text, 'executing'::text, 'verifying'::text, 'completed'::text, 'blocked'::text, 'paused'::text, 'rejected'::text, 'abandoned'::text, 'failed'::text])));
alter table public.missions add constraint missions_title_check CHECK (((length(title) >= 3) AND (length(title) <= 140)));
alter table public.missions add constraint missions_verdict_check CHECK ((verdict = ANY (ARRAY['GO'::text, 'TEST'::text, 'DEFER'::text, 'REJECT'::text])));
alter table public.outbox add constraint outbox_channel_check CHECK ((channel = ANY (ARRAY['text'::text, 'email'::text, 'call'::text, 'post'::text, 'telegram'::text])));
alter table public.outbox add constraint outbox_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'qa_passed'::text, 'approved'::text, 'sent'::text, 'rejected'::text])));
alter table public.owner_messages add constraint owner_messages_channel_check CHECK ((channel = ANY (ARRAY['telegram'::text, 'text'::text, 'call'::text])));
alter table public.owner_messages add constraint owner_messages_decision_check CHECK ((decision = ANY (ARRAY['approved'::text, 'rejected'::text])));
alter table public.owner_messages add constraint owner_messages_kind_check CHECK ((kind = ANY (ARRAY['brief'::text, 'money'::text, 'health'::text, 'contract'::text, 'proposal'::text, 'emergency'::text])));
alter table public.system_state add constraint system_state_id_check CHECK ((id = 1));
alter table public.system_state add constraint system_state_mode_check CHECK ((mode = ANY (ARRAY['dry_run'::text, 'approve_first'::text, 'auto_in_caps'::text, 'exceptions_only'::text])));
alter table public.tasks add constraint tasks_status_check CHECK ((status = ANY (ARRAY['todo'::text, 'doing'::text, 'blocked'::text, 'done'::text, 'cancelled'::text])));
alter table public.tool_registry add constraint tool_registry_kind_check CHECK ((kind = ANY (ARRAY['api'::text, 'saas'::text, 'bot'::text, 'workflow'::text, 'number'::text, 'domain'::text, 'other'::text])));
alter table public.tool_registry add constraint tool_registry_status_check CHECK ((status = ANY (ARRAY['active'::text, 'idle'::text, 'cancelled'::text, 'trial'::text])));
alter table public.ventures add constraint ventures_kind_check CHECK ((kind = ANY (ARRAY['revenue'::text, 'personal'::text, 'lab'::text])));
alter table public.ventures add constraint ventures_status_check CHECK ((status = ANY (ARRAY['active'::text, 'paused'::text, 'parked'::text, 'cut'::text])));
